   331	        int maxBytes,
   332	        CancellationToken cancellationToken)
   333	    {
   334	        if (content is null)
   335	        {
   336	            return new ResponseBody("", false);
   337	        }
   338	
   339	        await using var stream = await content.ReadAsStreamAsync(cancellationToken);
   340	        using var body = new MemoryStream();
   341	        var buffer = new byte[Math.Min(DefaultStreamCopyBufferSize, maxBytes + 1)];
   342	
   343	        while (true)
   344	        {
   345	            var remaining = maxBytes - (int)body.Length;
   346	            var readLength = Math.Min(buffer.Length, remaining + 1);
   347	            var read = await stream.ReadAsync(buffer.AsMemory(0, readLength), cancellationToken);
   348	            if (read == 0)
   349	            {
   350	                return new ResponseBody(DecodeBody(content, body.ToArray()), false);
   351	            }
   352	
   353	            if (body.Length + read > maxBytes)
   354	            {
   355	                var allowed = maxBytes - (int)body.Length;
   356	                if (allowed > 0)
   357	                {
   358	                    body.Write(buffer, 0, allowed);
   359	                }
   360	
   361	                return new ResponseBody(DecodeBody(content, body.ToArray()), true);
   362	            }
   363	
   364	            body.Write(buffer, 0, read);
   365	        }
   366	    }
