   673	internal static class CommentJson
   674	{
   675	    // Defensive client-side ceilings for the current comment API boundary.
   676	    // They keep malformed or compromised responses from producing unbounded
   677	    // agent context/stdout while allowing normal comment payload sizes. These
   678	    // are not a server contract; update the constants and tests together if
   679	    // the API publishes larger supported limits.
   680	    private const int MaxComments = 1000;
   681	    private const int MaxAuthorLength = 256;
   682	    private const int MaxTimestampLength = 128;
   683	    private const int MaxContentLength = 8192;
   684	
   685	    private static readonly string[] CreatedCommentIdPropertyNames = ["id", "commentId"];
   686	    private static readonly string[] CommentArrayPropertyNames = ["comments", "items", "data"];
   687	    private static readonly string[] TimestampPropertyNames = ["timestamp", "createdAt", "createdOn", "created", "updatedAt"];
   688	    private static readonly string[] ContentPropertyNames = ["content", "body", "text"];
   689	    private static readonly string[] NestedAuthorPropertyNames = ["displayName", "name", "email", "id"];
   690	    private static readonly string[] FallbackAuthorPropertyNames = ["authorName", "createdBy", "createdByName", "userName", "userId"];
   691	
   692	    // The service has returned these aliases across scaffold iterations. Keep
   693	    // accepted names centralized so the API boundary remains easy to audit.
   694	    public static string ExtractCreatedCommentId(string raw)
   695	    {
   696	        if (string.IsNullOrWhiteSpace(raw))
   697	        {
   698	            throw new InvalidOperationException("API response did not include a comment id.");
   699	        }
   700	
   701	        using var document = ParseDocument(raw);
   702	        var root = document.RootElement;
   703	        if (root.ValueKind == JsonValueKind.String)
   704	        {
   705	            var value = root.GetString();
   706	            if (!string.IsNullOrWhiteSpace(value))
   707	            {
   708	                return value;
   709	            }
   710	        }
   711	
   712	        if (FirstScalar(root, CreatedCommentIdPropertyNames) is { } id ||
   713	            TryGetNestedScalar(root, "comment", "id", out id))
   714	        {
   715	            if (!string.IsNullOrWhiteSpace(id))
   716	            {
   717	                return id;
   718	            }
   719	        }
   720	
   721	        throw new InvalidOperationException("API response did not include a comment id.");
   722	    }
   723	
   724	    public static IReadOnlyList<TaskComment> ReadComments(string raw)
   725	    {
   726	        if (string.IsNullOrWhiteSpace(raw))
   727	        {
   728	            throw new InvalidOperationException("API response was not a comment array or wrapper object.");
   729	        }
   730	
   731	        using var document = ParseDocument(raw);
   732	        var root = document.RootElement;
   733	        var comments = new List<TaskComment>();
   734	        foreach (var comment in EnumerateCommentElements(root))
   735	        {
   736	            if (comments.Count >= MaxComments)
   737	            {
   738	                throw new InvalidOperationException($"API returned more than {MaxComments} comments.");
   739	            }
   740	
   741	            comments.Add(ReadComment(comment, comments.Count));
   742	        }
   743	
   744	        return comments;
   745	    }
