   747	    private static TaskComment ReadComment(JsonElement comment, int index)
   748	    {
   749	        if (comment.ValueKind != JsonValueKind.Object)
   750	        {
   751	            throw new InvalidOperationException($"API comment at index {index} was not an object.");
   752	        }
   753	
   754	        return new TaskComment(
   755	            RequiredAuthor(comment, index),
   756	            RequiredScalar(comment, index, "timestamp", MaxTimestampLength, TimestampPropertyNames),
   757	            RequiredScalar(comment, index, "content", MaxContentLength, ContentPropertyNames));
   758	    }
   759	
   760	    private static JsonDocument ParseDocument(string raw)
   761	    {
   762	        try
   763	        {
   764	            return JsonDocument.Parse(raw);
   765	        }
   766	        catch (JsonException exception)
   767	        {
   768	            throw new InvalidOperationException("API response was malformed JSON.", exception);
   769	        }
   770	    }
