   772	    private static IEnumerable<JsonElement> EnumerateCommentElements(JsonElement root)
   773	    {
   774	        if (root.ValueKind == JsonValueKind.Array)
   775	        {
   776	            foreach (var comment in root.EnumerateArray())
   777	            {
   778	                yield return comment;
   779	            }
   780	
   781	            yield break;
   782	        }
   783	
   784	        if (root.ValueKind == JsonValueKind.Object)
   785	        {
   786	            foreach (var propertyName in CommentArrayPropertyNames)
   787	            {
   788	                if (TryGetProperty(root, propertyName, out var property))
   789	                {
   790	                    if (property.ValueKind == JsonValueKind.Array)
   791	                    {
   792	                        foreach (var comment in property.EnumerateArray())
   793	                        {
   794	                            yield return comment;
   795	                        }
   796	
   797	                        yield break;
   798	                    }
   799	
   800	                    throw new InvalidOperationException(
   801	                        $"API response property '{propertyName}' was not a comment array.");
   802	                }
   803	            }
   804	
   805	            throw new InvalidOperationException(
   806	                "API response did not include a comments, items, or data comment array.");
   807	        }
   808	
   809	        throw new InvalidOperationException("API response was not a comment array or wrapper object.");
   810	    }
