   818	                return BoundedScalar(authorValue, index, "author", MaxAuthorLength);
   819	            }
   820	
   821	            if (author.ValueKind == JsonValueKind.Object)
   822	            {
   823	                var nestedAuthor = FirstScalar(author, NestedAuthorPropertyNames);
   824	                if (nestedAuthor is not null)
   825	                {
   826	                    return BoundedScalar(nestedAuthor, index, "author", MaxAuthorLength);
   827	                }
   828	            }
   829	        }
   830	
   831	        var fallbackAuthor = FirstScalar(comment, FallbackAuthorPropertyNames);
   832	        if (fallbackAuthor is not null)
   833	        {
   834	            return BoundedScalar(fallbackAuthor, index, "author", MaxAuthorLength);
   835	        }
   836	
   837	        throw new InvalidOperationException($"API comment at index {index} did not include an author.");
   838	    }
