   846	    {
   847	        var value = FirstScalar(root, propertyNames);
   848	        if (value is not null)
   849	        {
   850	            return BoundedScalar(value, index, fieldName, maxLength);
   851	        }
   852	
   853	        throw new InvalidOperationException(
   854	            $"API comment at index {index} did not include a {fieldName}.");
   855	    }
   856	
   857	    private static string BoundedScalar(string value, int index, string fieldName, int maxLength)
   858	    {
   859	        if (value.Length <= maxLength)
   860	        {
   861	            return value;
   862	        }
   863	
   864	        throw new InvalidOperationException(
   865	            $"API comment at index {index} {fieldName} exceeded {maxLength} characters.");
   866	    }
