   868	    private static bool TryGetNestedScalar(JsonElement root, string propertyName, string nestedPropertyName, out string value)
   869	    {
   870	        value = "";
   871	        if (!TryGetProperty(root, propertyName, out var property) || property.ValueKind != JsonValueKind.Object)
   872	        {
   873	            return false;
   874	        }
   875	
   876	        return TryGetScalar(property, nestedPropertyName, out value);
   877	    }
