   879	    private static string? FirstScalar(JsonElement root, params string[] propertyNames)
   880	    {
   881	        foreach (var propertyName in propertyNames)
   882	        {
   883	            if (TryGetScalar(root, propertyName, out var value))
   884	            {
   885	                return value;
   886	            }
   887	        }
   888	
   889	        return null;
