   892	    private static bool TryGetScalar(JsonElement root, string propertyName, out string value)
   893	    {
   894	        value = "";
   895	        if (!TryGetProperty(root, propertyName, out var property))
   896	        {
   897	            return false;
   898	        }
   899	
   900	        return TryConvertScalar(property, out value);
   901	    }
