   903	    private static bool TryGetProperty(JsonElement root, string propertyName, out JsonElement property)
   904	    {
   905	        property = default;
   906	        if (root.ValueKind != JsonValueKind.Object)
   907	        {
   908	            return false;
   909	        }
   910	
   911	        foreach (var candidate in root.EnumerateObject())
   912	        {
   913	            if (StringComparer.OrdinalIgnoreCase.Equals(candidate.Name, propertyName))
   914	            {
   915	                property = candidate.Value;
   916	                return true;
   917	            }
   918	        }
   919	
   920	        return false;
   921	    }
